mkdir -p /app/bin /app/out; cat > /app/bin/fees.py <<'EOF'
import sys, os, csv, json, re, configparser, io
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal


def cents(s):
    return int((Decimal(str(s).strip()) * 100).to_integral_value())


def pdate(s):
    return date.fromisoformat(s.strip())


def pnum(s):
    d = re.sub(r'\D', '', str(s))
    return int(d) if d else 0


def parse_off(s):
    s = s.strip()
    m = re.fullmatch(r'([+-])(\d\d):?(\d\d)', s)
    mins = int(m.group(2)) * 60 + int(m.group(3))
    return timedelta(minutes=-mins if m.group(1) == '-' else mins)


def read_csv(path):
    with open(path, encoding='utf-8-sig', newline='') as f:
        rows = list(csv.DictReader(f))
    return [{(k or '').strip(): (v or '').strip() for k, v in r.items()} for r in rows]


def main(inp, outp):
    cp = configparser.ConfigParser(interpolation=None, inline_comment_prefixes=None)
    cp.optionxform = str.lower
    with open(os.path.join(inp, 'policy.ini'), encoding='utf-8-sig') as f:
        cp.read_file(f)
    library = cp.get('statement', 'library').strip()
    pstart = pdate(cp.get('statement', 'period_start'))
    pend = pdate(cp.get('statement', 'period_end'))
    base_off = parse_off(cp.get('clock', 'offset'))
    changes = []
    ch = cp.get('clock', 'changes', fallback='').strip()
    for part in ch.split(';'):
        part = part.strip()
        if not part:
            continue
        t, o = part.split()
        t = datetime.strptime(t, '%Y-%m-%dT%H:%MZ').replace(tzinfo=timezone.utc)
        changes.append((t, parse_off(o)))
    changes.sort(key=lambda x: x[0])

    items = {}
    cats = {}
    for sec in cp.sections():
        if sec.lower().startswith('item:'):
            s = cp[sec]
            items[sec[5:].strip().lower()] = dict(
                name=sec[5:].strip(), loan_days=int(s['loan_days']), renewals=int(s['renewals']),
                grace=int(s['grace_days']), daily=cents(s['daily']), cap=cents(s['loan_cap']))
        elif sec.lower().startswith('category:'):
            s = cp[sec]
            sc = s.get('statement_cap', 'none').strip()
            cats[sec[9:].strip().lower()] = dict(
                name=sec[9:].strip(), cap=None if sc.lower() == 'none' or not sc else cents(sc),
                discount=int(s.get('discount', '0').strip() or 0),
                exempt={x.strip().lower() for x in s.get('exempt', '').split(',') if x.strip()})

    branches = read_csv(os.path.join(inp, 'branches.csv'))
    bkey = {}
    open_days = {}
    for b in branches:
        bkey[b['branch'].lower()] = b['branch']
        open_days[b['branch']] = {w.lower()[:3] for w in b['open_days'].split()}
    wd = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun']

    cal = {}  # branch or '*' -> list of (first,last,status)
    for r in read_csv(os.path.join(inp, 'calendar.csv')):
        d = r['date']
        if '..' in d:
            a, b = d.split('..')
        else:
            a = b = d
        br = r['branch'].strip()
        br = '*' if br == '*' else bkey.get(br.lower(), br)
        cal.setdefault(br, []).append((pdate(a), pdate(b), r['status'].strip().lower()))

    def is_open(br, d):
        for key in (br, '*'):
            for a, b, st in cal.get(key, ()):
                if a <= d <= b:
                    return st == 'open'
        return wd[d.weekday()] in open_days.get(br, set())

    def next_open(br, d):
        for _ in range(3660):
            if is_open(br, d):
                return d
            d += timedelta(days=1)
        return d

    patron_rows = {}
    for r in read_csv(os.path.join(inp, 'patrons.csv')):
        patron_rows.setdefault(pnum(r['patron']), []).append((pdate(r['since']), r['patron'], r['category']))
    for v in patron_rows.values():
        v.sort(key=lambda x: x[0])

    def category(pn, d):
        best = None
        for since, _, c in patron_rows.get(pn, ()):
            if since <= d:
                best = c
        if best is None and patron_rows.get(pn):
            best = patron_rows[pn][0][2]
        return cats[best.lower()]

    # events
    events = {}
    edir = os.path.join(inp, 'exports')
    for fn in sorted(os.listdir(edir)):
        path = os.path.join(edir, fn)
        low = fn.lower()
        if not (low.endswith('.csv') or low.endswith('.jsonl')) or not os.path.isfile(path):
            continue
        recs = []
        if low.endswith('.csv'):
            for r in read_csv(path):
                t = r.get('time', '')
                if not r.get('event'):
                    continue
                r['_local'] = datetime.strptime(t, '%Y-%m-%d %H:%M')
                recs.append(r)
        else:
            with open(path, encoding='utf-8-sig') as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    o = json.loads(line)
                    r = {k: ('' if v is None else str(v).strip()) for k, v in o.items()}
                    at = r['at']
                    if at.endswith('Z') or at.endswith('z'):
                        at = at[:-1] + '+00:00'
                    m = re.fullmatch(r'(.*?)([+-]\d\d):?(\d\d)', at)
                    if m:
                        at = m.group(1) + m.group(2) + ':' + m.group(3)
                    dt = datetime.fromisoformat(at)
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=timezone.utc)
                    utc = dt.astimezone(timezone.utc)
                    off = base_off
                    for t, o2 in changes:
                        if utc >= t:
                            off = o2
                    r['_local'] = (utc + off).replace(tzinfo=None)
                    recs.append(r)
        for r in recs:
            events.setdefault(r['event'], r)

    cancelled = set()
    for e in events.values():
        if e.get('type', '').lower() == 'void' and e.get('target'):
            cancelled.add(e['target'])
    live = [e for e in events.values()
            if e.get('type', '').lower() != 'void' and e['event'] not in cancelled]

    loans = {}
    for e in live:
        if e['type'].lower() == 'checkout':
            d = e['_local'].date()
            if d > pend:
                continue
            br = bkey.get(e['branch'].lower(), e['branch'])
            loans[e['loan']] = dict(id=e['loan'], patron=pnum(e['patron']), item=e.get('item', ''),
                                    it=items[e['item_type'].lower()], branch=br, checkout=d, ev=[])
    for e in live:
        t = e['type'].lower()
        if t in ('renew', 'return') and e.get('loan') in loans:
            loans[e['loan']]['ev'].append((e['_local'], t, e))

    waivers = []
    for r in read_csv(os.path.join(inp, 'waivers.csv')):
        if r['status'].lower() != 'active':
            continue
        v = r['value'].strip()
        waivers.append((pnum(r['patron']), r['loan'].strip(), None if v.lower() == 'full' else cents(v)))

    stm = {}
    for L in loans.values():
        it = L['it']
        due = next_open(L['branch'], L['checkout'] + timedelta(days=it['loan_days']))
        nren = 0
        ret = None
        for lt, t, e in sorted(L['ev'], key=lambda x: x[0]):
            ld = lt.date()
            if t == 'renew':
                if ld <= due and nren < it['renewals'] and ld <= pend:
                    nren += 1
                    due = next_open(L['branch'], ld + timedelta(days=it['loan_days']))
            else:
                ret = ld - timedelta(days=1) if e.get('via', '').lower() == 'dropbox' else ld
                break
        if ret is not None and ret < pstart:
            continue
        if ret is not None and ret > pend:
            ret = None
        end = ret if ret is not None else pend
        od = 0
        d = due + timedelta(days=1)
        while d <= end:
            if is_open(L['branch'], d):
                od += 1
            d += timedelta(days=1)
        if od < 1:
            continue
        charged = od if od > it['grace'] else 0
        cat = category(L['patron'], L['checkout'])
        base = charged * it['daily']
        if it['name'].lower() in cat['exempt'] or it['name'].lower() in cat['exempt']:
            base = 0
        base = min(base, it['cap'])
        assessed = (base * (100 - cat['discount']) * 2 + 100) // 200
        full = False
        amt = 0
        for wp, wl, wv in waivers:
            if wp == L['patron'] and (wl == '*' or wl == L['id']):
                if wv is None:
                    full = True
                else:
                    amt += wv
        waived = assessed if full else min(amt, assessed)
        L.update(due=due, ret=ret, od=od, charged=charged, assessed=assessed, waived=waived,
                 net=assessed - waived, capped=0)
        stm.setdefault(L['patron'], []).append(L)

    out_st = []
    bsum = {b['branch']: dict(branch=b['branch'], loans=0, charged_days=0, assessed=0, waived=0, capped=0, billed=0)
            for b in branches}
    for pn in sorted(stm):
        ls = stm[pn]
        cat = category(pn, pend)
        total = sum(l['net'] for l in ls)
        if cat['cap'] is not None and total > cat['cap']:
            excess = total - cat['cap']
            for l in sorted(ls, key=lambda l: (l['due'], l['id']), reverse=True):
                g = min(excess, l['net'])
                l['capped'] = g
                excess -= g
        ls.sort(key=lambda l: (l['due'], l['id']))
        rows = []
        for l in ls:
            billed = l['net'] - l['capped']
            rows.append({"loan": l['id'], "item": l['item'], "item_type": l['it']['name'],
                         "branch": l['branch'], "checkout": l['checkout'].isoformat(),
                         "due": l['due'].isoformat(),
                         "returned": l['ret'].isoformat() if l['ret'] else None,
                         "overdue_days": l['od'], "charged_days": l['charged'],
                         "assessed": l['assessed'], "waived": l['waived'], "capped": l['capped'],
                         "billed": billed})
            b = bsum.get(l['branch'])
            if b is not None:
                b['loans'] += 1
                b['charged_days'] += l['charged']
                for k in ('assessed', 'waived', 'capped'):
                    b[k] += l[k]
                b['billed'] += billed
        out_st.append({"patron": patron_rows[pn][0][1], "category": cat['name'], "loans": rows,
                       **{k: sum(r[k] for r in rows) for k in ('assessed', 'waived', 'capped', 'billed')}})
    res = {"library": library, "period": {"start": pstart.isoformat(), "end": pend.isoformat()},
           "statements": out_st, "branches": list(bsum.values())}
    with open(outp, 'w', encoding='utf-8') as f:
        json.dump(res, f, indent=2)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
